 "recipeIngredient": [
  "240 grams (2 cups) all-purpose flour",
  "14 grams (1 tablespoon) baking powder",
  "1 \u00bc teaspoons kosher salt",
  "113 grams (\u00bd cup, 1 stick) unsalted butter, very cold and cut into small pieces",
  "170-227 grams (\u00be- 1 cup, 180-240 milliliters) milk or buttermilk"
 ],
 "recipeInstructions": [
  {
   "@type": "HowToStep",
   "text": "Preheat the oven to 450\u00b0F/230\u00b0C",
   "position": 1,
   "name": "Preheat the oven to 450\u00b0F/230\u00b0C",
   "url": "https://bakerbettie.com/5-ingredient-basic-drop-biscuits/#mv_create_193_1"
  },
  {
   "@type": "HowToStep",
   "text": "In a large bowl, whisk together flour (240 grams/ 2 cups), baking powder (14 grams/ 1 tablespoon), and salt (1 \u00bc teaspoons) together.",
   "position": 2,
   "name": "In a large bowl, whisk together flour (240...",
   "url": "https://bakerbettie.com/5-ingredient-basic-drop-biscuits/#mv_create_193_2"
  },
  {
   "@type": "HowToStep",
   "text": "Add the pieces of cold butter (113 grams/ \u00bd cup) and cut into the dry ingredients with a pastry cutter or fork until the consistency of coarse meal. If you want to add any cheeses or other add-ins you can stir them in here before adding the milk.",
   "position": 3,
   "name": "Add the pieces of cold butter (113 grams/...",
   "url": "https://bakerbettie.com/5-ingredient-basic-drop-biscuits/#mv_create_193_3"
  },
  {
   "@type": "HowToStep",
   "text": "Add the smaller amount of the milk or buttermilk (170 grams/ \u00be cup) and stir just until combined. If the batter is very dry, add a little more milk until the consistency resembles a very thick batter. Do not over-mix. The batter will be quite lumpy.",
   "position": 4,
   "name": "Add the smaller amount of the milk or...",
   "url": "https://bakerbettie.com/5-ingredient-basic-drop-biscuits/#mv_create_193_4"
  },
  {
   "@type": "HowToStep",
   "text": "Drop large mounds (about \u00bc cup each, I like to use a 2 ounce cookie scoop) onto either a parchment lined baking sheet or buttered cast iron skillet. The mounds can be touching on the sides.",
   "position": 5,
   "name": "Drop large mounds (about \u00bc cup each, I...",
   "url": "https://bakerbettie.com/5-ingredient-basic-drop-biscuits/#mv_create_193_5"
  },
  {
   "@type": "HowToStep",
   "text": "Bake for 16-20 minutes until golden brown.",
   "position": 6,
   "name": "Bake for 16-20 minutes until golden brown.",
   "url": "https://bakerbettie.com/5-ingredient-basic-drop-biscuits/#mv_create_193_6"
  },
  {
   "@type": "HowToStep",
   "text": "Brush with melted butter and sprinkle with flaky salt if desired.",
   "position": 7,
   "name": "Brush with melted butter and sprinkle with flaky...",
   "url": "https://bakerbettie.com/5-ingredient-basic-drop-biscuits/#mv_create_193_7"
  }
 ],
 "video": {
  "@type": "VideoObject",
  "name": "Easy Drop Biscuits &amp; Garlic Cheddar Biscuits",
  "description": "This easy drop biscuit recipe only requires 5 simple ingredients! In under 30 minutes you can have homemade drop biscuits on your table! I also decided to add some garlic and cheddar to the biscuits to make a delicious variation. These taste exactly like the Cheddar Bay Biscuits you can get at Red Lobster, but I think they're better! \n\nFULL EASY DROP BISCUIT RECIPE \u25ba https://bakerbettie.com/5-ingredient-basic-drop-biscuits/\nGARLIC CHEESE BISCUIT RECIPE \u25ba https://bakerbettie.com/garlic-cheese-biscuits/\nSUBSCRIBE \u25ba https://www.youtube.com/c/BakerBettie?sub_confirmation=1\nBetter Baking School \u25bahttps://betterbakingschool.com/\n-------------------------------------------------------------------------\nORDER THE BAKER BETTIE COOKBOOK! \nAmazon- http://bit.ly/BetterBakingBook\nBookshop- http://bit.ly/Betterbakingbook\nBarnes and noble- http://bit.ly/BetterBakingbook\nChapters indigo- http://bit.ly/BetterbakingBook\nIndiebound- http://bit.ly/betterbakingbook\n--------------------------------------------------------------------------\nINGREDIENTS: \n2 cups (240 gr) all-purpose flour\n1 TBSP (14 gr) baking powder\n1 tsp (4 gr) salt\n1/2 tsp garlic powder\n1/2 cup (1 stick, 112 gr) cold butter, (salted or unsalted)\n2 cups (200 gr) shredded sharp cheddar cheese\n1 cup (240 ml) milk or buttermilk\n-------------------------------------------------------------------------\nPRODUCTS USED IN THIS RECIPE (affiliate links)\nCast Iron Skillet: https://amzn.to/3forueE\n2 oz Scoop: https://amzn.to/2SDNCrs\nPastry Brush: https://amzn.to/2yyJ8Mb\n---------------------------------------------------------------------------\nFOLLOW ME ON: \nFacebook: http://www.facebook.com/bakerbettie\nInstagram: http://instagram.com/bakerbettie\nEmail Subscription: https://bit.ly/2RJS1ZA\nWebsite: http://BakerBettie.com",
  "thumbnailUrl": "https://i.ytimg.com/vi/gUxdDz6izKI/hqdefault.jpg",
  "contentUrl": "https://www.youtube.com/watch?v=gUxdDz6izKI",
  "duration": "PT5M26S",
  "uploadDate": "2020-04-17T19:56:13Z"
 },
